# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: reflex-kernel UI: chat with the Smash agent across the top; below, the
#          results it pulled (r1, r2, ...) as tabs side by side with Jupyter-style Python
#          cells that share the same variables. This file is layout and chrome; how a
#          value is shown (grid, videos, fields) is render.py. Built from design_poc's /split.
# Usage: cd experimental/reflex-kernel && uv run reflex run   (http://localhost:3000)
# ---------------------------------------------------------------------------
from __future__ import annotations

import reflex as rx

from .api import api
from .editor import cell_editor
from .render import render_component
from .state import State

# Nerd Font glyphs (JetBrainsMono Nerd Font): python logo, robot, table.
ICON_PY = ""
ICON_CHAT, ICON_RESULTS = "\U000f06a9", "\U000f04eb"
# Two diagonal arrows pointing apart / together, as on Zed's zoom button.
ICON_EXPAND, ICON_COLLAPSE = "\U000f0616", "\U000f0615"
# The editor fetches completions straight from the backend (see api.py).
COMPLETE_URL = rx.config.get_config().api_url + "/complete"


def handle(name: rx.Var | str) -> rx.Component:
    """A named table that both the agent and the Python cells can refer to."""
    return rx.el.span(name, class_name="handle mono")


def zoom_button(pane: str) -> rx.Component:
    """Fill the window with this pane, or restore the layout. assets/panes.js clicks it on Ctrl+Shift+F."""
    return rx.el.button(
        rx.cond(State.zoomed == pane, ICON_COLLAPSE, ICON_EXPAND),
        title=rx.cond(State.zoomed == pane, "Restore panes (Ctrl+Shift+F)", "Full screen (Ctrl+Shift+F)"),
        on_click=State.toggle_zoom(pane),
        class_name=rx.cond(State.zoomed == pane, "zoom-btn mono is-on", "zoom-btn mono"),
    )


def chat_item(item: rx.Var) -> rx.Component:
    return rx.match(
        item["kind"],
        ("user", rx.el.div(item["text"], class_name="bubble is-user")),
        (
            "step",
            rx.el.div(
                rx.el.span("▸", class_name="dim"),
                rx.el.span(item["name"], class_name="tool-name"),
                rx.el.span(item["text"], class_name="tool-args"),
                class_name="tool-step mono",
            ),
        ),
        (
            "ref",
            rx.el.button(
                handle(item["name"]),
                rx.el.span(item["text"], class_name="dim"),
                rx.el.span("open →", class_name="ref-open"),
                on_click=State.select_object(item["name"]),
                class_name="ref",
            ),
        ),
        ("error", rx.el.pre(item["text"], class_name="bubble is-error mono")),
        rx.el.div(rx.markdown(item["text"]), class_name="bubble md"),
    )


def agent_progress() -> rx.Component:
    """The one "agent is working" status, at the end of the chat: a pulsing 3x3 dot square, as in Zed's agent panel."""
    return rx.el.div(
        rx.el.span(*[rx.el.i() for _ in range(9)], class_name="dot-square"),
        rx.el.span(rx.cond(State.streaming == "", "Thinking…", "Generating…")),
        class_name="agent-progress",
    )


def chat_pane() -> rx.Component:
    return rx.el.div(
        rx.el.div(rx.el.span("Chat"), rx.el.span(class_name="spacer"), zoom_button("chat"), class_name="pane-title"),
        # column-reverse keeps the scroll pinned to the newest message
        rx.el.div(
            rx.el.div(
                rx.cond(
                    State.chat.length() == 0,
                    rx.el.div(
                        "Ask about Smash Ultimate. What the agent pulls (tables, match videos, …) shows up below as r1, r2, … ",
                        "and is a plain Python object in the cells (tables are polars DataFrames).",
                        class_name="empty",
                    ),
                ),
                rx.foreach(State.chat, chat_item),
                rx.cond(
                    State.busy & (State.streaming != ""),
                    rx.el.div(rx.markdown(State.streaming), class_name="bubble md"),
                ),
                rx.cond(State.busy, agent_progress()),
                class_name="chat-items",
            ),
            class_name="chat-scroll",
        ),
        rx.el.form(
            rx.el.textarea(
                name="prompt",
                placeholder="Ask the agent…  (Enter to send, Shift+Enter for a new line)",
                enter_key_submit=True,
                # the cursor starts here when the app opens
                auto_focus=True,
                rows=2,
                class_name="input sans",
            ),
            on_submit=State.send_chat,
            reset_on_submit=True,
            class_name="composer",
        ),
        class_name=rx.match(
            State.chat_layout,
            ("hidden", "chat-pane sans is-hidden"),
            ("alone", "chat-pane sans is-alone"),
            "chat-pane sans",
        ),
        custom_attrs={"data-pane": "chat"},
    )


def object_tab(obj: rx.Var) -> rx.Component:
    return rx.el.button(
        handle(obj["name"]),
        rx.el.span(obj["shape"]),
        rx.el.span(obj["source"], class_name="dim"),
        on_click=State.select_object(obj["name"]),
        class_name=rx.cond(State.selected == obj["name"], "tab is-active", "tab"),
    )


def viewer() -> rx.Component:
    """The selected tab: just the value's own component (render.py)."""
    return render_component(State.view, State.view_event)


def trace_part(part: rx.Var) -> rx.Component:
    """One piece of a traceback (session.trace_parts): the full standard traceback, styled by role."""
    return rx.match(
        part["kind"],
        (
            "frame",
            rx.el.div(
                rx.el.div(
                    rx.el.span(part["path"], class_name="tb-path"),
                    rx.el.span(", line ", class_name="dim"),
                    rx.el.span(part["line"], class_name="tb-line"),
                    rx.cond(
                        part["func"] != "",
                        rx.el.span(
                            rx.el.span(", in ", class_name="dim"), rx.el.span(part["func"], class_name="tb-func")
                        ),
                    ),
                ),
                rx.cond(
                    (part["pre"] != "") | (part["mark"] != ""),
                    rx.el.div(
                        part["pre"],
                        rx.el.span(part["mark"], class_name="tb-mark"),
                        part["post"],
                        class_name="tb-code",
                    ),
                ),
                class_name="tb-frame is-" + part["where"].to(str),
            ),
        ),
        (
            "error",
            rx.el.div(
                rx.el.span(part["module"], class_name="tb-module"),
                rx.el.span(part["name"], class_name="tb-name"),
                rx.cond(part["text"] != "", rx.el.span(": ", part["text"], class_name="tb-msg")),
                class_name="tb-error",
            ),
        ),
        ("chain", rx.el.div(part["text"], class_name="tb-chain")),
        rx.el.div(part["text"], class_name="tb-dim"),
    )


def cell_view(cell: rx.Var) -> rx.Component:
    """One notebook cell: In[n] gutter, CodeMirror editor, output underneath."""
    return rx.el.div(
        rx.el.div(
            rx.el.span("[", rx.cond(cell.count == "", " ", cell.count), "]", class_name="cell-count mono"),
            rx.el.div(
                cell_editor(
                    initial_code=cell.code,
                    complete_url=COMPLETE_URL,
                    token=State.token,
                    on_run=lambda code, advance: State.run_cell(cell.id, code, advance),
                    on_save=lambda code: State.save_code(cell.id, code),
                ),
                class_name="cell-editor",
            ),
            rx.el.button("▶", title="Run (Ctrl+Enter)", on_click=State.run_saved(cell.id), class_name="cell-btn"),
            rx.el.button("×", title="Delete cell", on_click=State.delete_cell(cell.id), class_name="cell-btn"),
            class_name="cell-in",
        ),
        rx.cond(cell.stdout != "", rx.el.pre(cell.stdout, class_name="cell-out mono")),
        # the result's view, under a small bar; render.py picks the component for its kind
        rx.cond(
            cell.view.kind != "",
            # the same component as a tab shows, sized to its content
            render_component(
                cell.view,
                State.view_event,
                compact=True,
                actions=(
                    rx.el.button(
                        "↗ tab",
                        title="Open as a tab on the left (bound as out<n>)",
                        on_click=State.open_output(cell.id),
                        class_name="act",
                    ),
                ),
            ),
        ),
        rx.cond(cell.text != "", rx.el.pre(cell.text, class_name="cell-out mono")),
        rx.cond(
            cell.trace.length() > 0,
            # bottom of the traceback always shown; everything above it collapsed in a <details>
            rx.el.div(
                rx.cond(
                    cell.trace_hidden.length() > 0,
                    rx.el.details(
                        rx.el.summary(cell.trace_more, class_name="tb-toggle sans"),
                        rx.foreach(cell.trace_hidden, trace_part),
                    ),
                ),
                rx.foreach(cell.trace, trace_part),
                class_name="cell-trace mono",
            ),
            rx.cond(cell.error != "", rx.el.pre(cell.error, class_name="cell-out is-error mono")),
        ),
        key=cell.id,
        class_name="cell",
    )


def notebook() -> rx.Component:
    return rx.el.div(
        rx.el.div(
            rx.el.span(rx.el.span(ICON_PY, class_name="mono accent-green icon"), "Python"),
            rx.el.span(
                "Shift+Enter run and advance · Ctrl+Enter run · Tab complete",
                class_name="dim",
            ),
            rx.el.span(class_name="spacer"),
            rx.cond(State.running, rx.el.span("running…", class_name="dim")),
            rx.el.button("Run all", on_click=State.run_all, class_name="act"),
            rx.el.button("Clear outputs", on_click=State.clear_outputs, class_name="act"),
            rx.el.button("+ Cell", on_click=State.add_cell, class_name="act"),
            zoom_button("python"),
            class_name="console-head sans",
        ),
        rx.el.div(rx.foreach(State.cells, cell_view), class_name="notebook-body"),
        # hidden with CSS, not unmounted, so the editors keep their text and cursor
        class_name=rx.cond(State.python_on, "console", "console is-hidden"),
        custom_attrs={"data-pane": "python"},
    )


def tables_pane() -> rx.Component:
    return rx.el.div(
        rx.el.div(
            rx.el.div(
                rx.foreach(State.objects, object_tab),
                rx.cond(~State.has_objects, rx.el.span("no results yet", class_name="tab dim")),
                class_name="tabs",
            ),
            zoom_button("results"),
            class_name="tabbar sans",
        ),
        rx.el.div(
            rx.cond(
                State.has_objects,
                viewer(),
                rx.el.div(
                    "Results appear here when the agent pulls data (tables, match videos, …), ",
                    "or when you make a DataFrame in the Python cells, eg ",
                    rx.el.code('chars = db.sql("select * from char")'),
                    class_name="empty sans",
                ),
            ),
            class_name="ws-widget",
        ),
        class_name=rx.match(
            State.pane_layout,
            ("hidden", "ws-pane is-hidden"),
            ("alone", "ws-pane is-alone"),
            "ws-pane",
        ),
        custom_attrs={"data-pane": "results"},
    )


def pane_toggle(pane: str, icon: str, label: str, shown: rx.Var[bool]) -> rx.Component:
    return rx.el.button(
        icon,
        title=f"Show or hide {label}",
        aria_label=f"Show or hide {label}",
        on_click=State.toggle_pane(pane),
        class_name=rx.cond(shown, "pane-toggle mono is-on", "pane-toggle mono"),
    )


def statusbar() -> rx.Component:
    """Bottom bar, as in Zed: one toggle per pane."""
    return rx.el.div(
        pane_toggle("chat", ICON_CHAT, "chat", State.show_chat),
        pane_toggle("results", ICON_RESULTS, "results", State.show_results),
        pane_toggle("python", ICON_PY, "Python", State.show_python),
        rx.el.span(class_name="spacer"),
        rx.cond(State.busy, rx.el.span("agent working…", class_name="dim")),
        rx.cond(State.running, rx.el.span("python running…", class_name="dim")),
        class_name="statusbar sans",
    )


def index() -> rx.Component:
    return rx.el.div(
        rx.el.div(
            rx.el.span("SmashGPT", class_name="title"),
            rx.el.span(class_name="spacer"),
            class_name="titlebar sans",
        ),
        rx.el.div(
            chat_pane(),
            rx.el.div(
                tables_pane(),
                notebook(),
                class_name=rx.cond(State.results_on | State.python_on, "bottom-split", "bottom-split is-hidden"),
            ),
            class_name="split-main",
        ),
        statusbar(),
        class_name="page",
    )


# theme=None: no Radix theme wrapper, all styling comes from assets/app.css.
app = rx.App(
    theme=None,
    stylesheets=["/app.css"],
    api_transformer=api,
    head_components=[
        rx.el.link(rel="icon", href="/favicon.png", type="image/png"),
        rx.el.link(rel="apple-touch-icon", href="/apple-touch-icon.png"),
        # Ctrl+Shift+F: full screen for the pane you are in
        rx.el.script(src="/panes.js", defer=True),
    ],
)
# The page title is the web app window's title (SmashGPT); see .os/scripts/keybindings/smashgpt.py.
app.add_page(index, route="/", title="SmashGPT", on_load=State.on_load)
